using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Tools;

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo(string message) => $"Echo: {message}";

    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer.Resources;

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "App Settings",
        Description = "Returns the current application configuration.")]
    public static string GetAppSettings()
    {
        return """
            {
              "appName": "McpHttpServer",
              "version": "1.0.0",
              "environment": "production",
              "features": {
                "enableLogging": true,
                "maxRetries": 3
              }
            }
            """;
    }

    [McpServerResource(UriTemplate = "config://app/status",
        Name = "App Status",
        Description = "Returns the current application health status.")]
    public static string GetAppStatus()
    {
        return $$"""
            {
              "status": "healthy",
              "uptime": "{{TimeSpan.FromMilliseconds(Environment.TickCount64)}}",
              "timestamp": "{{DateTimeOffset.UtcNow:O}}"
            }
            """;
    }
}

